var a=`0444-korvapuusti`;var i=`world-0444`;var o=`FI`;var t=`northern-europe`;var u=8;var r=102;var l={en:`Korvapuusti`,ua:`Корвапуусті`};var d={en:`A traditional dish from Finland, centered on all-purpose flour, whole cow milk, instant yeast, chicken egg. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Фінляндія. Основні складники: пшеничне борошно універсальне, цільне коров'яче молоко, інстантні дріжджі, куряче яйце. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Mix and knead into a supple yeast dough. Cover and leave in a warm place until roughly doubled, about 65 minutes.`,ua:`Змішайте й вимісіть м’яке дріжджове тісто. Накрийте та поставте в тепле місце до збільшення об’єму приблизно вдвічі, орієнтовно на 65 хвилин.`,t:[`mixing`,`kneading`,`bulk-fermentation`],m:65,i:[[`all-purpose-flour`,480,`g`],[`whole-cow-milk`,260,`ml`],[`instant-yeast`,7,`g`],[`white-granulated-sugar`,75,`g`],[`unsalted-butter`,75,`g`],[`ground-cardamom`,5,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:4,i:[[`unsalted-butter`,80,`g`],[`white-granulated-sugar`,70,`g`],[`ground-cinnamon`,14,`g`]]},{en:`Divide and shape the dough as required. Place on a lined tray and proof for about 14 minutes while the oven heats.`,ua:`Поділіть і сформуйте тісто відповідно до виробу. Викладіть на деко з пергаментом і залиште підходити приблизно на 14 хвилин, поки гріється духовка.`,t:[`pre-shaping-dough`,`final-proofing`],m:14,i:[]},{en:`Bake in a preheated 180°C oven for about 19 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 19 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:19,i:[[`chicken-egg`,1,`pcs`]]}];var s={slug:a,id:i,country:`FI`,region:t,servings:8,minutes:102,title:l,text:d,steps:g};export{o as country,s as default,i as id,r as minutes,t as region,u as servings,a as slug,g as steps,d as text,l as title};